<?php
require_once '../config/db.php'; require_once '../includes/auth.php'; require_login();
$search=trim($_GET['property_no']??''); $properties=[];
if($search!==''){$s=$pdo->prepare("SELECT id,property_code,property_no,scheme_name,price,status FROM properties WHERE property_no LIKE ? OR property_code LIKE ? ORDER BY property_no");$like="%$search%";$s->execute([$like,$like]);$properties=$s->fetchAll();}
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Online Payments</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/css/style.css" rel="stylesheet"></head><body><div class="portal-wrapper"><header class="portal-header"><div class="portal-brand">💳 Online Payments</div><div class="portal-header-actions"><a href="admin.php" class="btn btn-sm btn-outline-light">Dashboard</a><a href="../logout.php" class="btn btn-sm btn-light">Logout</a></div></header><main class="portal-main"><div class="portal-page-header"><h1 class="portal-page-title">Online Payment Search</h1><p class="portal-page-subtitle">Property number ya Property ID se search karke payment record karein.</p></div><div class="dashboard-shell mb-3"><form class="row g-2"><div class="col-md-10"><input name="property_no" class="form-control" required value="<?= htmlspecialchars($search) ?>" placeholder="Enter property no. or property ID"></div><div class="col-md-2"><button class="btn btn-primary w-100">Search</button></div></form></div><?php if($search!==''): ?><div class="dashboard-shell table-responsive"><table class="table align-middle"><thead><tr><th>S.No.</th><th>Property</th><th>Scheme</th><th>Price</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($properties as $i=>$p): ?><tr><td><?= $i+1 ?></td><td><?= htmlspecialchars($p['property_code']) ?><br><?= htmlspecialchars($p['property_no']) ?></td><td><?= htmlspecialchars($p['scheme_name']) ?></td><td>₹<?= number_format($p['price'],2) ?></td><td><?= htmlspecialchars($p['status']) ?></td><td><a href="payments.php?property_id=<?= $p['id'] ?>" class="btn btn-sm btn-primary">Open Payment</a></td></tr><?php endforeach; ?><?php if(!$properties): ?><tr><td colspan="6" class="text-center text-muted">No property found.</td></tr><?php endif; ?></tbody></table></div><?php endif; ?></main></div></body></html>
